// Keep only in-scope festival shows entering the -30 min window and
// not already alerted (dedupe via workflow static data).
const LEAD_MIN = 30;
const POIS = {
  'Palco Mundo': [-22.975420, -43.395110],
  'Palco Sunset': [-22.973810, -43.397020],
  'Espaço Favela': [-22.974910, -43.393540],
  'New Dance Order': [-22.977230, -43.396250],
  'Gourmet Square': [-22.976100, -43.394800],
  'Entrada / BRT': [-22.979500, -43.392000]
};
function resolveStage(text) {
  const t = (text || '').toLowerCase();
  if (t.includes('palco mundo')) return 'Palco Mundo';
  if (t.includes('sunset')) return 'Palco Sunset';
  if (t.includes('favela')) return 'Espaço Favela';
  if (t.includes('new dance order') || t.includes('ndo')) return 'New Dance Order';
  if (t.includes('gourmet')) return 'Gourmet Square';
  return null;
}
const store = this.getWorkflowStaticData('global');
store.alerted = store.alerted || {};
const now = Date.now();
const out = [];
for (const item of items) {
  const ev = item.json;
  const summary = ev.summary || '';
  const location = ev.location || '';
  const blob = (summary + ' ' + location + ' ' + (ev.description || '')).toLowerCase();
  if (!blob.includes('rock in rio') && !resolveStage(blob)) continue;
  const stage = resolveStage(blob);
  if (!stage) continue;
  const startIso = ev.start && (ev.start.dateTime || ev.start.date);
  if (!startIso) continue;
  const start = new Date(startIso).getTime();
  const deltaMin = (start - now) / 60000;
  if (deltaMin <= 0 || deltaMin > LEAD_MIN) continue;
  if (store.alerted[ev.id]) continue;
  store.alerted[ev.id] = now;
  const artist = summary.split(/\s*[-–—@|:]\s*/)[0].replace(/rock in rio/ig, '').trim() || summary;
  const time = new Date(startIso).toLocaleTimeString('pt-BR', { hour: '2-digit', minute: '2-digit', timeZone: 'America/Sao_Paulo' });
  out.push({ json: { event_id: ev.id, artist, stage, time, start: startIso } });
}
return out;

