// Normalise Meta inbound payload to { kind, lat, lng, button_id, text }.
const body = items[0].json.body || items[0].json;
const out = [];
for (const entry of (body.entry || [])) {
  for (const change of (entry.changes || [])) {
    for (const m of ((change.value || {}).messages || [])) {
      if (m.type === 'location') {
        out.push({ json: { kind: 'location', lat: Number(m.location.latitude), lng: Number(m.location.longitude) } });
      } else if (m.type === 'interactive') {
        const r = (m.interactive.button_reply || m.interactive.list_reply || {});
        out.push({ json: { kind: 'button', button_id: r.id, text: r.title } });
      } else if (m.type === 'text') {
        out.push({ json: { kind: 'text', text: (m.text || {}).body || '' } });
      }
    }
  }
}
return out.length ? out : [{ json: { kind: 'ignore' } }];

// Resolve the active target stage (from Redis-less static data) and, for a
// button check-in, substitute the fixed POI coordinates.
const POIS = {
  'checkin_palco_sunset': [-22.973810, -43.397020],
  'checkin_gourmet_square': [-22.976100, -43.394800],
  'checkin_espaco_favela': [-22.974910, -43.393540],
  'checkin_entrada_brt': [-22.979500, -43.392000]
};
const store = this.getWorkflowStaticData('global');
const target = store.activeShow || { stage: 'Palco Mundo' };
const j = items[0].json;
let lat = j.lat, lng = j.lng;
if (j.button_id && POIS[j.button_id]) { [lat, lng] = POIS[j.button_id]; }
return [{ json: { lat, lng, stage: target.stage } }];

// Parse Distance Matrix, fall back to Haversine @ 4.5 km/h.
function haversine(a, b, c, d) {
  const R = 6371000, r = Math.PI / 180;
  const p1 = a * r, p2 = c * r, dp = (c - a) * r, dl = (d - b) * r;
  const x = Math.sin(dp/2)**2 + Math.cos(p1)*Math.cos(p2)*Math.sin(dl/2)**2;
  return 2 * R * Math.asin(Math.sqrt(x));
}
const DEST = {'Palco Mundo':[-22.975420,-43.395110],'Palco Sunset':[-22.973810,-43.397020],'Espaço Favela':[-22.974910,-43.393540],'New Dance Order':[-22.977230,-43.396250],'Gourmet Square':[-22.976100,-43.394800],'Entrada / BRT':[-22.979500,-43.392000]};
const prev = $('Prep Distance Matrix').first().json;
const api = items[0].json;
let distance_m, duration_min, method;
try {
  const el = api.rows[0].elements[0];
  if (el.status !== 'OK') throw new Error(el.status);
  distance_m = el.distance.value;
  duration_min = Math.max(1, Math.round(el.duration.value / 60));
  method = 'distance_matrix';
} catch (e) {
  const [dlat, dlng] = DEST[prev.stage];
  const raw = haversine(prev.lat, prev.lng, dlat, dlng) * 1.25;
  distance_m = Math.round(raw);
  duration_min = Math.max(1, Math.ceil(distance_m / (4500 / 60)));
  method = 'haversine_fallback';
}
return [{ json: { distance_m, duration_min, method, stage: prev.stage } }];

